const auditCases=[
 {pattern:'Earlier concentration',why:'The highest three-year count in the prepared study: 9 crashes. Eight occurred in 2023–2024 and one in 2025.',question:'Does the current layout still present the conditions that warrant investigation in the earlier reports?',first:'Review the site’s change history alongside the earlier reports, then inspect current crossing and turning conditions.'},
 {pattern:'Recurrence in all three years',why:'Reports recur in each year: 2, 3 and 3. Six of the eight crashes involved a cyclist.',question:'Where do turning paths and walking or cycling movements interact under present-day conditions?',first:'Observe turning movements, sight lines and walking/cycling continuity; collect volumes to interpret the recurring reports.'},
 {pattern:'Earlier concentration',why:'Seven reported crashes, including five pedestrian-involved crashes; annual counts are 4, 2 and 1.',question:'Are crossing visibility, turning interactions and pedestrian continuity adequate today?',first:'Review crossing conditions and recent changes. The declining count does not demonstrate a reduction in risk.'},
 {pattern:'Recurrence; map match unresolved',why:'Six crashes with annual counts of 1, 2 and 3; five involved a cyclist. The official GIS node match is not unique or verified.',question:'Which precise public intersection does the normalized label refer to, and what should the field audit cover?',first:'Reconcile the intersection label and verify the road location before scheduling a site-specific visit. Retain it in the study shortlist.'},
 {pattern:'Earlier concentration',why:'Five of six reports occurred in 2023, one in 2024 and none in 2025.',question:'Did the layout, reporting or travel volumes change after the earlier concentration?',first:'Check change history and present-day conditions before interpreting the zero count in 2025. Zero reports do not establish safety.'},
 {pattern:'Intermittent recurrence',why:'Six crashes are distributed 4, 0 and 2 across 2023–2025. Four involved a cyclist and two a pedestrian.',question:'What explains the reporting gap, and do present-day crossing or turning conditions merit intervention?',first:'Review the site history and reporting context; inspect current visibility, turning movements and walking/cycling connections.'}
];
let selectedAudit=0;
function drawAudit(){const l=shortlist[selectedAudit],c=auditCases[selectedAudit];$('audit-choices').innerHTML=shortlist.map((q,i)=>`<button class="audit-choice" data-audit="${i}" aria-pressed="${i===selectedAudit}"><span class="candidate-letter">${'ABCDEF'[i]}</span><span><strong>${esc(nice(q.name))}</strong><small>${q.total} crashes · ${auditCases[i].pattern}</small></span></button>`).join('');
 $('audit-brief').innerHTML=`<div class="brief-heading"><span class="pill">FIXED STUDY · 2023–2025</span><button id="print-audit">Print this audit brief</button></div><h3>${'ABCDEF'[selectedAudit]} · ${esc(nice(l.name))}</h3><p class="brief-decision"><strong>Recommended next step:</strong> ${c.first}</p><div class="brief-evidence"><div><b>${l.total}</b><span>eligible crashes</span></div><div><b>${l.annual.join(' / ')}</b><span>2023 / 2024 / 2025</span></div><div><b>${l.cyclist} / ${l.pedestrian}</b><span>cyclist / pedestrian</span></div></div><div class="brief-columns"><div><h4>Why investigate here?</h4><p>${c.why}</p><h4>Lead question for the audit</h4><p>${c.question}</p></div><div><h4>Before recommending an intervention</h4><ul><li>Verify the current layout and recent or planned projects.</li><li>Observe crossings, sight lines, turning movements and route continuity.</li><li>Collect pedestrian, cyclist and vehicle volumes.</li><li>Reconcile location and reporting uncertainties with the source records.</li></ul></div></div><p class="brief-caution"><strong>Decision boundary:</strong> This evidence supports investigation, not a causal finding, risk-per-trip estimate or final capital priority. These audit questions are hypotheses to investigate, not established deficiencies.</p><div class="brief-links"><button id="audit-explore">Explore this location’s counts →</button><a href="#priorities">Compare all six candidates</a></div><p class="note">Source: Cambridge CPD log, downloaded September 17, 2026. One combined count per eligible record; involvement categories may overlap. This fixed brief is unaffected by exploratory filters.</p>`;
 $('audit-choices').querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedAudit=+b.dataset.audit;drawAudit()});
 $('audit-explore').onclick=()=>{$('year').value='all';$('mode').value='all';$('location').value=l.name;mapState.selected=l.name;if(l.coord){mapState.center=[...l.coord];mapState.zoom=3}render();$('explore').scrollIntoView({behavior:'smooth'})};
 $('print-audit').onclick=()=>{$('print-brief').innerHTML='<h1>Cambridge road safety audit brief</h1>'+$('audit-brief').innerHTML;window.print()};
}
window.selectAudit=name=>{const i=shortlist.findIndex(l=>l.name===name);if(i>=0){selectedAudit=i;drawAudit()}};
drawAudit();
